package com.sunrise.dentalclinic.service;
import com.sunrise.dentalclinic.dto.*;import com.sunrise.dentalclinic.exception.*;import com.sunrise.dentalclinic.model.Patient;import com.sunrise.dentalclinic.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class PatientService{private final PatientRepository repo;private final AppointmentRepository appointments;private final BillRepository bills;public PatientService(PatientRepository r,AppointmentRepository a,BillRepository b){repo=r;appointments=a;bills=b;}@Transactional(readOnly=true)public List<Patient> search(String q){if(q==null||q.isBlank())return repo.findAll();var found=new ArrayList<>(repo.findByNameContainingIgnoreCaseOrContactNumberContainingIgnoreCaseOrderByName(q,q));try{repo.findById(Long.valueOf(q.trim())).filter(p->found.stream().noneMatch(x->x.getId().equals(p.getId()))).ifPresent(found::add);}catch(NumberFormatException ignored){}return found;}@Transactional(readOnly=true)public List<PatientListItem> list(String q){return search(q).stream().map(p->PatientListItem.from(p,appointments.countByPatientId(p.getId()))).toList();}@Transactional(readOnly=true)public Patient get(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Patient not found"));}@Transactional(readOnly=true)public List<PatientAppointmentHistory> history(Long id){get(id);return appointments.findByPatientIdOrderByAppointmentDateDescAppointmentTimeDesc(id).stream().map(a->PatientAppointmentHistory.from(a,bills.findByAppointmentId(a.getId()).map(x->x.getId()).orElse(null))).toList();}@Transactional public Patient create(PatientRequest r){return repo.save(map(new Patient(),r));}@Transactional public Patient update(Long id,PatientRequest r){return repo.save(map(get(id),r));}@Transactional public void delete(Long id){var patient=get(id);if(appointments.existsByPatientId(id))throw new BusinessException("This patient cannot be deleted because appointment or billing records exist.");repo.delete(patient);}private Patient map(Patient p,PatientRequest r){p.setName(r.name().trim());p.setAddress(r.address().trim());p.setContactNumber(r.contactNumber().trim());return p;}}
